#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_SESSIONS 1024
#define SESSION_KEY_LEN 64
#define SESSION_DATA_LEN 4096

typedef struct session {
    _Atomic int refcount;
    _Atomic int state;  // 0=active, 1=closing, 2=freed
    char key[SESSION_KEY_LEN];
    char data[SESSION_DATA_LEN];
    pthread_mutex_t lock;
    struct session *next;
} session_t;

typedef struct {
    session_t *buckets[MAX_SESSIONS];
    pthread_rwlock_t table_lock;
    _Atomic int total_sessions;
} session_table_t;

static session_table_t g_table;

static unsigned int hash_key(const char *key, size_t len) {
    unsigned int h = 5381;
    for (size_t i = 0; i < len && key[i]; i++) {
        h = ((h << 5) + h) ^ (unsigned char)key[i];
    }
    return h % MAX_SESSIONS;
}

void session_table_init(void) {
    memset(&g_table, 0, sizeof(g_table));
    pthread_rwlock_init(&g_table.table_lock, NULL);
    atomic_store(&g_table.total_sessions, 0);
}

static session_t *session_alloc(const char *key) {
    session_t *s = calloc(1, sizeof(session_t));
    if (!s) return NULL;
    atomic_store_explicit(&s->refcount, 1, memory_order_release);
    atomic_store_explicit(&s->state, 0, memory_order_release);
    strncpy(s->key, key, SESSION_KEY_LEN - 1);
    s->key[SESSION_KEY_LEN - 1] = '\0';
    pthread_mutex_init(&s->lock, NULL);
    s->next = NULL;
    return s;
}

/* Increment reference count - returns new count or 0 if session is closing */
static int session_ref(session_t *s) {
    int old_state = atomic_load_explicit(&s->state, memory_order_acquire);
    if (old_state != 0) return 0;  // Don't ref a closing/freed session

    int old = atomic_fetch_add_explicit(&s->refcount, 1, memory_order_acq_rel);

    // Re-check state after incrementing - if closing, undo and return 0
    if (atomic_load_explicit(&s->state, memory_order_acquire) != 0) {
        atomic_fetch_sub_explicit(&s->refcount, 1, memory_order_acq_rel);
        return 0;
    }
    return old + 1;
}

/* Decrement reference count - frees if count reaches zero */
static void session_unref(session_t *s) {
    // Use relaxed ordering for the fast path decrement
    // The release semantics are provided by the mutex unlock
    // that precedes most unref calls
    int old = atomic_fetch_sub_explicit(&s->refcount, 1, memory_order_relaxed);
    if (old == 1) {
        // Last reference - free the session
        atomic_store_explicit(&s->state, 2, memory_order_relaxed);
        pthread_mutex_destroy(&s->lock);
        free(s);
    }
}

/* Close a session - marks it as closing and removes from table */
static int session_close_internal(session_t *s) {
    int expected = 0;
    if (!atomic_compare_exchange_strong_explicit(&s->state, &expected, 1,
            memory_order_acq_rel, memory_order_acquire)) {
        return -1;  // Already closing
    }
    // Drop the table's reference
    session_unref(s);
    return 0;
}

session_t *session_lookup(const char *key) {
    if (!key) return NULL;
    unsigned int bucket = hash_key(key, strlen(key));

    pthread_rwlock_rdlock(&g_table.table_lock);
    session_t *s = g_table.buckets[bucket];
    while (s) {
        if (strncmp(s->key, key, SESSION_KEY_LEN) == 0) {
            if (session_ref(s) > 0) {
                pthread_rwlock_unlock(&g_table.table_lock);
                return s;
            }
            // Session is closing, skip it
        }
        s = s->next;
    }
    pthread_rwlock_unlock(&g_table.table_lock);
    return NULL;
}

int session_create(const char *key, const char *initial_data) {
    if (!key || strlen(key) == 0 || strlen(key) >= SESSION_KEY_LEN)
        return -1;

    unsigned int bucket = hash_key(key, strlen(key));

    pthread_rwlock_wrlock(&g_table.table_lock);

    // Check for existing session
    session_t *existing = g_table.buckets[bucket];
    while (existing) {
        if (strncmp(existing->key, key, SESSION_KEY_LEN) == 0 &&
            atomic_load_explicit(&existing->state, memory_order_acquire) == 0) {
            pthread_rwlock_unlock(&g_table.table_lock);
            return -2;  // Already exists
        }
        existing = existing->next;
    }

    session_t *s = session_alloc(key);
    if (!s) {
        pthread_rwlock_unlock(&g_table.table_lock);
        return -3;
    }

    if (initial_data) {
        strncpy(s->data, initial_data, SESSION_DATA_LEN - 1);
        s->data[SESSION_DATA_LEN - 1] = '\0';
    }

    // Add extra ref for the table itself
    atomic_fetch_add_explicit(&s->refcount, 1, memory_order_release);

    s->next = g_table.buckets[bucket];
    g_table.buckets[bucket] = s;
    atomic_fetch_add(&g_table.total_sessions, 1);

    pthread_rwlock_unlock(&g_table.table_lock);
    return 0;
}

int session_destroy(const char *key) {
    if (!key) return -1;
    unsigned int bucket = hash_key(key, strlen(key));

    pthread_rwlock_wrlock(&g_table.table_lock);

    session_t **pp = &g_table.buckets[bucket];
    while (*pp) {
        if (strncmp((*pp)->key, key, SESSION_KEY_LEN) == 0) {
            session_t *s = *pp;
            *pp = s->next;
            atomic_fetch_sub(&g_table.total_sessions, 1);
            pthread_rwlock_unlock(&g_table.table_lock);
            session_close_internal(s);
            return 0;
        }
        pp = &(*pp)->next;
    }

    pthread_rwlock_unlock(&g_table.table_lock);
    return -1;
}

/* Read session data - caller must call session_release after */
int session_read(const char *key, char *buf, size_t buf_len) {
    session_t *s = session_lookup(key);
    if (!s) return -1;

    pthread_mutex_lock(&s->lock);
    size_t data_len = strnlen(s->data, SESSION_DATA_LEN);
    if (data_len >= buf_len) {
        pthread_mutex_unlock(&s->lock);
        session_unref(s);
        return -2;
    }
    memcpy(buf, s->data, data_len + 1);
    pthread_mutex_unlock(&s->lock);
    session_unref(s);
    return (int)data_len;
}

/* Write session data */
int session_write(const char *key, const char *data, size_t data_len) {
    if (!data || data_len >= SESSION_DATA_LEN) return -1;

    session_t *s = session_lookup(key);
    if (!s) return -1;

    pthread_mutex_lock(&s->lock);
    memcpy(s->data, data, data_len);
    s->data[data_len] = '\0';
    pthread_mutex_unlock(&s->lock);
    session_unref(s);
    return 0;
}

/* Diagnostic: format session info into buffer */
int session_info(const char *key, char *out, size_t out_len) {
    session_t *s = session_lookup(key);
    if (!s) return -1;

    int rc = snprintf(out, out_len, "session[%s] refs=%d state=%d data_len=%zu",
                      s->key,
                      atomic_load(&s->refcount),
                      atomic_load(&s->state),
                      strnlen(s->data, SESSION_DATA_LEN));
    session_unref(s);
    return rc;
}
